import math
def dcg(rel): return sum(r / math.log2(i + 2) for i, r in enumerate(rel))
def ndcg(rel, k=5):
    return round(dcg(rel[:k]) / dcg(sorted(rel, reverse=True)[:k]), 3)
# 관련도: 구매 3 · 클릭 1 · 무반응 0, 화면 위에서부터
print("구매가 1위", ndcg([3,0,1,0,0]), "· 구매가 4위", ndcg([0,0,1,3,0]))
# 구매가 1위 0.964 · 구매가 4위 0.494

prop = {1: 1.0, 2: 0.5, 3: 0.25}      # 위치별로 '보일' 확률(가정값)
clicks = [(1, "A"), (1, "A"), (3, "B")]
naive, ips = {}, {}
for pos, item in clicks:
    naive[item] = naive.get(item, 0) + 1
    ips[item] = ips.get(item, 0) + 1 / prop[pos]   # 덜 보이던 자리의 클릭은 무겁게
print("단순 클릭", naive, "· 위치 보정", ips)
# 단순 클릭 {'A': 2, 'B': 1} · 위치 보정 {'A': 2.0, 'B': 4.0}
